#!/bin/bash
# Codex SessionStart hook — generated by scripts/gen-harness-codex.ts, do not edit.
# Hands scripts/codex-rules.txt to the main session as hookSpecificOutput.additionalContext.
# The prime digest rides its own hook (session-digest.sh). Nothing here fails the hook.

cat > /dev/null
ROOT="${PLUGIN_ROOT:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)}"
CONTEXT=$(cat "$ROOT/scripts/codex-rules.txt" 2>/dev/null)
if [ -z "$CONTEXT" ]; then
  exit 0
fi

jq -n --arg context "$CONTEXT" '{
  hookSpecificOutput: {
    hookEventName: "SessionStart",
    additionalContext: $context
  }
}'
exit 0
